tests.code:
const heading = document.querySelector('.card h1');
const intro = document.querySelector('.card p');
expect(heading).not.toBeNull();
expect(intro).not.toBeNull();
expect(heading.textContent.trim()).not.toBe('');
expect(intro.textContent.trim()).not.toBe('');

const link = document.querySelector('.profile-link');
const image = link?.querySelector('img');
expect(image).not.toBeNull();
expect(image.getAttribute('src')).toMatch(/^(data:image|https?:\/\/)/);
expect(image.getAttribute('alt').trim()).not.toBe('');
expect(link.getAttribute('href')).toMatch(/^https?:\/\//);

